import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long a = Long.parseLong(next());
        long b = Long.parseLong(next());
        long c = Long.parseLong(next());
        long d = Long.parseLong(next());

        int size = (int) n;
        int[] dx = {1, 2, -1, -2, 1, 2, -1, -2}, dy = {2, 1, 2, 1, -2, -1, -2, -1};
        int[][] dist = new int[size][size];
        for (int[] row : dist) Arrays.fill(row, -1);
        dist[(int) a - 1][(int) b - 1] = 0;
        List<int[]> queue = new ArrayList<>();
        queue.add(new int[] {(int) a - 1, (int) b - 1});
        for (int i = 0; i < queue.size(); i++) {
            int x = queue.get(i)[0], y = queue.get(i)[1];
            for (int k = 0; k < 8; k++) {
                int p = x + dx[k], q = y + dy[k];
                if (p >= 0 && p < size && q >= 0 && q < size && dist[p][q] < 0) {
                    dist[p][q] = dist[x][y] + 1;
                    queue.add(new int[] {p, q});
                }
            }
        }
        System.out.println(dist[(int) c - 1][(int) d - 1]);
    }
}
